@using sv_fdffce21cb964dddab6dc64f023dd369.Services

<div class="settings-section">
    <h3>Security Settings</h3>

    @if (Settings is null)
    {
        <p>Loading...</p>
        return;
    }

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    <!-- Change Password Panel -->
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center"
             style="cursor:pointer" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>Change Password</span>
            <span>@(_passwordExpanded ? "▲" : "▼")</span>
        </div>
        @if (_passwordExpanded)
        {
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="_currentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="_newPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control" @bind="_confirmPassword" />
                </div>
                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating..." : "Update Password")
                </button>
                @if (Settings.LastPasswordChange.HasValue)
                {
                    <small class="text-muted ms-3">Last changed: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</small>
                }
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="card mb-4">
        <div class="card-body d-flex align-items-center gap-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@Settings.TwoFactorEnabled" disabled />
                <label class="form-check-label" for="twoFactor">Two-Factor Authentication</label>
            </div>
            <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-warning")">
                @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="card mb-4">
        <div class="card-header">Active Sessions</div>
        <div class="card-body">
            <div class="table-responsive">
                <table class="table table-striped">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("MMM dd, yyyy HH:mm")</td>
                                <td>
                                    @if (session != Settings.Sessions.FirstOrDefault())
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => ShowRevokeDialog(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>
    </div>

    <RevokeSessionDialog Visible="_revokeDialogVisible"
                         Session="_sessionToRevoke"
                         OnConfirm="RevokeSessionAsync"
                         OnCancel="() => { _revokeDialogVisible = false; _sessionToRevoke = null; }" />
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string current, string newPw)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _message;
    private bool _isError;

    private bool _revokeDialogVisible;
    private ActiveSession? _sessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        if (_newPassword != _confirmPassword)
        {
            _message = "New passwords do not match.";
            _isError = true;
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword) || string.IsNullOrWhiteSpace(_currentPassword))
        {
            _message = "All password fields are required.";
            _isError = true;
            return;
        }

        _changingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
            _message = "Password updated successfully!";
            _isError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _message = $"Failed to update password: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void ShowRevokeDialog(ActiveSession session)
    {
        _sessionToRevoke = session;
        _revokeDialogVisible = true;
    }

    private async Task RevokeSessionAsync()
    {
        if (_sessionToRevoke is null) return;
        await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
        _revokeDialogVisible = false;
        _message = $"Session on {_sessionToRevoke.Device} has been revoked.";
        _isError = false;
        _sessionToRevoke = null;
    }
}
"}

