@namespace sv_fdffce21cb964dddab6dc64f023dd369.Components.Pages.Settings
@using sv_fdffce21cb964dddab6dc64f023dd369.Services

<div class="settings-section">
    <h3>Appearance Settings</h3>

    @if (Settings is null)
    {
        <p>Loading...</p>
        return;
    }

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-6">
            <!-- Theme -->
            <div class="mb-4">
                <h5>Theme</h5>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <h5>Font Size</h5>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"size-{size}")"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"size-{size}")">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="mb-4">
                <h5>Language</h5>
                <select class="form-select" @bind="_language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
        </div>

        <!-- Live Preview -->
        <div class="col-md-6">
            <h5>Preview</h5>
            <div class="appearance-preview p-3 border rounded"
                 style="@GetPreviewStyle()">
                <h6 style="@GetFontStyle()">Sample Heading</h6>
                <p style="@GetFontStyle()" class="@(_compactMode ? "mb-1" : "mb-3")">
                    This is how your content will look with the selected settings.
                </p>
                <button class="btn btn-sm @(_theme == "Dark" ? "btn-light" : "btn-primary")">
                    Sample Button
                </button>
                <div class="mt-2" style="@GetFontStyle()">
                    <small class="text-muted">
                        Theme: @_theme | Font: @_fontSize | Compact: @(_compactMode ? "On" : "Off")
                    </small>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private string? _message;
    private bool _saving;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color: #1a1a2e; color: #e0e0e0;",
            "Light" => "background-color: #ffffff; color: #212529;",
            _ => "background-color: #f8f9fa; color: #212529;"
        };
        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1.5rem;";
        return $"{bg} {padding} min-height: 180px;";
    }

    private string GetFontStyle() => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.25rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _message = "Appearance settings saved!";
        _saving = false;
    }
}

