@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SectionChanged" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                break;
            case "Notifications":
                <NotificationsSection Prefs="@_notificationPrefs"
                                      AvailableChannels="@_availableChannels"
                                      OnSave="SaveNotificationPrefsAsync" />
                break;
            case "Security":
                <SecuritySection Settings="@_securitySettings"
                                 OnChangePassword="ChangePasswordAsync"
                                 OnRevokeSession="RevokeSessionAsync" />
                break;
            case "Appearance":
                <AppearanceSection Settings="@_appearanceSettings" OnSave="SaveAppearanceAsync" />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _securitySettings;
    private AppearanceSettings? _appearanceSettings;
    private List<string> _availableChannels = new() { "general", "announcements", "random", "dev", "design" };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionDataAsync();
    }

    private async Task SectionChanged(string section)
    {
        _activeSection = section;
        await LoadSectionDataAsync();
    }

    private async Task LoadSectionDataAsync()
    {
        switch (_activeSection)
        {
            case "Profile" when _profile is null:
                _profile = await SettingsService.GetProfileAsync();
                break;
            case "Notifications" when _notificationPrefs is null:
                _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security" when _securitySettings is null:
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance" when _appearanceSettings is null:
                _appearanceSettings = await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task ChangePasswordAsync((string current, string newPw) args)
    {
        await SettingsService.ChangePasswordAsync(args.current, args.newPw);
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 100px);
    gap: 0;
}

.settings-sidebar {
    width: 220px;
    background-color: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    flex-shrink: 0;
}

.settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background-color: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.settings-sidebar .sidebar-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 900px;
}

.settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

.appearance-preview {
    transition: all 0.2s ease;
}

